<script setup lang="ts">
import { ChevronDown, ChevronRight, ChevronLeft, ChevronsLeft, ChevronsRight, Pencil, Plus, Trash2, Search, RotateCw } from '@lucide/vue'
interface Row { id: string; name: string; bankCode?: string; contactPerson: string; contactNo: string; email: string }
interface GridState { rows: Row[]; page: number; pages: number; total: number; query: string; loading: boolean; error: string }
const props = withDefaults(defineProps<{ table: GridState; selected?: Row | null; branch?: boolean; busy?: boolean }>(), { selected: null, branch: false, busy: false })
const emit = defineEmits<{ create: []; edit: [row: Row]; remove: [row: Row]; select: [row: Row]; toggle: [row: Row]; search: []; refresh: []; paginate: [step: number]; query: [value: string]; clear: [] }>()
const selectionGroup = useId()
function selectRow(row: Row) {
  if (!props.busy && !props.table.loading) emit('select', row)
}
function clickRow(event: MouseEvent, row: Row) {
  // Controls have their own actions; clicking any ordinary cell selects the row.
  if ((event.target as HTMLElement).closest('button, input, a, select, textarea')) return
  selectRow(row)
}
const label = computed(() => props.branch ? 'branch' : 'bank')
</script>
<template>
  <section class="overflow-hidden rounded-xl border border-slate-200/80 bg-white shadow-[0_1px_2px_rgba(15,23,42,0.03)] dark:border-slate-800 dark:bg-[#15201e]" :aria-label="branch ? 'Bank branches child table' : 'Banks header table'" :aria-busy="table.loading">
    <div class="flex flex-wrap items-center justify-between gap-3 border-b border-slate-100 px-5 py-4 dark:border-slate-800"><div><h2 class="text-sm font-semibold text-slate-800 dark:text-slate-200">{{ branch ? 'Branches' : 'Banks' }}</h2><p class="mt-1 text-xs text-slate-400">{{ branch ? 'Click a row or its selector, then choose Edit or Delete.' : 'Click a row to select a bank and view its branches.' }}</p></div><span class="rounded-md bg-slate-50 px-2.5 py-1.5 text-[10px] font-medium text-slate-500 dark:bg-slate-800 dark:text-slate-400">{{ table.total }} {{ branch ? (table.total === 1 ? 'branch' : 'branches') : (table.total === 1 ? 'bank' : 'banks') }}</span></div>
    <div class="flex flex-wrap items-center gap-2 border-b border-slate-100 px-5 py-3 dark:border-slate-800" role="toolbar" :aria-label="`${branch ? 'Branch' : 'Bank'} actions`">
      <button class="inline-flex h-9 min-w-9 items-center justify-center rounded-lg px-2 text-xs font-semibold bg-brand-700 text-white shadow-sm shadow-brand-900/15 transition hover:bg-brand-800 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-brand-500 disabled:cursor-not-allowed disabled:opacity-40 " type="button" :disabled="busy || table.loading" :aria-label="`Add ${label}`" :title="`Add ${label}`" @click="emit('create')"><Plus :size="17" :stroke-width="2" /><span class="ml-1.5">Add {{ label }}</span></button>
      <button class="inline-flex h-9 min-w-9 items-center justify-center rounded-lg px-2 text-xs font-semibold text-slate-500 transition hover:bg-slate-100 hover:text-slate-800 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-brand-500 disabled:cursor-not-allowed disabled:opacity-40 dark:text-slate-400 dark:hover:bg-slate-800 dark:hover:text-white" type="button" :disabled="busy || table.loading || !selected" :aria-label="`Edit ${label}`" :title="selected ? `Edit ${selected.name}` : `Select a ${label} to edit`" @click="selected && emit('edit', selected)"><Pencil :size="14" /><span class="ml-1.5">Edit</span></button>
      <button class="inline-flex h-9 min-w-9 items-center justify-center rounded-lg px-2 text-xs font-semibold text-slate-500 transition hover:bg-slate-100 hover:text-slate-800 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-brand-500 disabled:cursor-not-allowed disabled:opacity-40 dark:text-slate-400 dark:hover:bg-slate-800 dark:hover:text-white" type="button" :disabled="busy || table.loading || !selected" :aria-label="`Delete ${label}`" :title="selected ? `Delete ${selected.name}` : `Select a ${label} to delete`" @click="selected && emit('remove', selected)"><Trash2 :size="14" /><span class="ml-1.5">Delete</span></button>
      <span class="mx-1 hidden h-6 w-px bg-slate-200 sm:block dark:bg-slate-700" />
      <form class="flex w-full items-center gap-1 sm:ml-auto sm:w-auto" @submit.prevent="emit('search')"><input :value="table.query" :disabled="busy" :aria-label="branch ? 'Search branches' : 'Search banks'" type="search" maxlength="160" :placeholder="branch ? 'Search branches…' : 'Search bank name or code…'" class="h-10 min-w-0 flex-1 rounded-lg border border-slate-200 bg-white px-3 text-xs text-slate-700 outline-none transition placeholder:text-slate-400 focus:border-brand-500 focus:ring-2 focus:ring-brand-100 sm:w-64 dark:border-slate-700 dark:bg-slate-900 dark:text-slate-200 dark:focus:ring-brand-900/30" @input="emit('query', ($event.target as HTMLInputElement).value)" /><button class="inline-flex h-8 min-w-8 items-center justify-center rounded-lg text-slate-400 transition hover:bg-slate-100 hover:text-slate-700 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-brand-500 disabled:cursor-not-allowed disabled:opacity-40 dark:hover:bg-slate-800 dark:hover:text-white" :disabled="busy || table.loading" type="submit" :aria-label="`Search ${branch ? 'branches' : 'banks'}`" title="Search"><Search :size="15" /></button></form>
      <button type="button" :disabled="busy || table.loading" :aria-label="`Refresh ${branch ? 'branches' : 'banks'}`" title="Refresh" @click="emit('refresh')"><RotateCw :size="14" :class="{ 'animate-spin': table.loading }" /></button>

    </div>
    <div class="flex min-h-10 flex-wrap items-center gap-2 border-b border-slate-100 bg-slate-50/60 px-5 py-2 text-xs dark:border-slate-800 dark:bg-slate-900/30">
      <p role="status" aria-live="polite" class="min-w-0 flex-1 text-slate-500 dark:text-slate-400"><template v-if="selected">Selected {{ label }}: <span class="font-semibold text-brand-800 dark:text-brand-200">{{ selected.name }}</span></template><template v-else>No {{ label }} selected. Select a row to enable Edit and Delete.</template></p>
      <button v-if="selected" type="button" :disabled="busy || table.loading" class="rounded px-2 py-1 text-[11px] font-semibold text-brand-700 hover:bg-brand-50 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-brand-500 disabled:opacity-40 dark:text-brand-300 dark:hover:bg-brand-900/30" :aria-label="`Clear ${label} selection`" @click="emit('clear')">Clear selection</button>
    </div>
    <p v-if="table.error" role="alert" class="m-4 rounded-lg border border-rose-200 bg-rose-50 px-4 py-3 text-xs text-rose-700 dark:border-rose-900/50 dark:bg-rose-950/30 dark:text-rose-300">{{ table.error }}</p>
    <div class="overflow-x-auto"><table class="w-full min-w-[760px] text-left text-xs"><caption class="sr-only">{{ branch ? 'Bank branches' : 'Banks and branches' }}</caption><thead class="bg-slate-50/70 text-[10px] font-semibold uppercase tracking-[0.1em] text-slate-400 dark:bg-slate-900/50"><tr><th class="w-10 px-4 py-3"><span class="sr-only">Select row</span></th><th v-if="!branch" class="w-12 px-3 py-3"><span class="sr-only">Expand branches</span></th><th class="px-4 py-3">{{ branch ? 'Bank Branch' : 'Bank Name' }}</th><th class="px-4 py-3">Contact Person</th><th class="px-4 py-3">Contact No</th><th class="px-4 py-3">Email</th><th v-if="!branch" class="px-4 py-3">Bank Code</th></tr></thead>
      <tbody class="divide-y divide-slate-100 dark:divide-slate-800">
        <tr v-if="table.loading"><td :colspan="branch ? 5 : 7" class="px-5 py-10 text-center text-xs text-slate-400" role="status">Loading {{ branch ? 'branches' : 'banks' }}…</td></tr>
        <template v-for="row in table.loading ? [] : table.rows" :key="row.id">
          <tr class="outline-none transition focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-brand-500" :class="[selected?.id === row.id ? 'bg-brand-50 shadow-[inset_3px_0_0_0_var(--color-brand-600)] hover:bg-brand-50 dark:bg-brand-900/30 dark:hover:bg-brand-900/30' : 'hover:bg-slate-50/70 dark:hover:bg-slate-900/40', busy ? 'cursor-default' : 'cursor-pointer']" :aria-selected="selected?.id === row.id" :tabindex="busy ? -1 : 0" @click="clickRow($event, row)" @keydown.enter.self.prevent="selectRow(row)" @keydown.space.self.prevent="selectRow(row)">
            <td class="w-10 px-4 py-3"><input type="radio" :name="selectionGroup" :checked="selected?.id === row.id" :disabled="busy" :aria-label="`Select ${label} row ${row.name}`" class="h-4 w-4 cursor-pointer accent-brand-700 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-brand-500 focus-visible:ring-offset-2 disabled:cursor-not-allowed dark:focus-visible:ring-offset-slate-900" @change="selectRow(row)" @click.stop /></td>
            <td v-if="!branch" class="w-12 px-3 py-3"><button type="button" class="inline-flex h-8 w-8 items-center justify-center rounded-lg text-slate-400 hover:bg-brand-50 hover:text-brand-700 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-brand-500 disabled:opacity-40 dark:hover:bg-brand-900/30 dark:hover:text-brand-300" :disabled="busy" :aria-label="`${selected?.id === row.id ? 'Collapse' : 'Expand'} branches for ${row.name}`" :aria-expanded="selected?.id === row.id" @click.stop="emit('toggle', row)"><ChevronDown v-if="selected?.id === row.id" :size="13" /><ChevronRight v-else :size="13" /></button></td>
            <td class="px-4 py-3.5 text-slate-500 dark:text-slate-400"><button type="button" :disabled="busy" class="w-full rounded text-left text-xs font-semibold text-slate-800 outline-none focus-visible:ring-2 focus-visible:ring-brand-500 dark:text-slate-200" :aria-label="`Select ${label} ${row.name}`" @click.stop="selectRow(row)">{{ row.name }}</button></td><td class="px-4 py-3.5 text-slate-500 dark:text-slate-400">{{ row.contactPerson || '—' }}</td><td class="px-4 py-3.5 text-slate-500 dark:text-slate-400">{{ row.contactNo || '—' }}</td><td class="px-4 py-3.5 text-slate-500 dark:text-slate-400">{{ row.email || '—' }}</td><td v-if="!branch" class="px-4 py-3.5 font-mono text-slate-500 dark:text-slate-400">{{ row.bankCode }}</td>
          </tr>
          <tr v-if="!branch && selected?.id === row.id"><td colspan="7" class="bg-slate-50/70 p-3 sm:p-5 sm:pl-12 dark:bg-slate-950/20"><div class="border-l-2 border-brand-200 pl-3 sm:pl-4 dark:border-brand-800"><slot name="branches" :bank="row" /></div></td></tr>
        </template>
        <tr v-if="!table.loading && !table.rows.length"><td :colspan="branch ? 5 : 7" class="px-5 py-10 text-center text-xs text-slate-400">{{ table.error ? 'Unable to load records. Try Refresh.' : `No ${branch ? 'branches' : 'banks'} found. Add one or try a different search.` }}</td></tr>
      </tbody>
    </table></div>
    <footer class="flex flex-wrap items-center justify-between gap-3 border-t border-slate-100 px-5 py-3 text-[10px] text-slate-400 dark:border-slate-800"><nav :aria-label="`${branch ? 'Branch' : 'Bank'} pagination`" class="flex items-center gap-1"><button class="inline-flex h-8 min-w-8 items-center justify-center rounded-lg text-slate-400 transition hover:bg-slate-100 hover:text-slate-700 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-brand-500 disabled:cursor-not-allowed disabled:opacity-40 dark:hover:bg-slate-800 dark:hover:text-white" :disabled="busy || table.loading || table.page <= 1" aria-label="First page" @click="emit('paginate', 1 - table.page)"><ChevronsLeft :size="14" /></button><button class="inline-flex h-8 min-w-8 items-center justify-center rounded-lg text-slate-400 transition hover:bg-slate-100 hover:text-slate-700 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-brand-500 disabled:cursor-not-allowed disabled:opacity-40 dark:hover:bg-slate-800 dark:hover:text-white" :disabled="busy || table.loading || table.page <= 1" aria-label="Previous page" @click="emit('paginate', -1)"><ChevronLeft :size="14" /></button><span class="inline-flex h-8 min-w-8 items-center justify-center rounded-lg bg-brand-700 px-2 text-xs font-semibold text-white" aria-current="page">{{ table.page }}</span><button class="inline-flex h-8 min-w-8 items-center justify-center rounded-lg text-slate-400 transition hover:bg-slate-100 hover:text-slate-700 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-brand-500 disabled:cursor-not-allowed disabled:opacity-40 dark:hover:bg-slate-800 dark:hover:text-white" :disabled="busy || table.loading || table.page >= table.pages" aria-label="Next page" @click="emit('paginate', 1)"><ChevronRight :size="14" /></button><button class="inline-flex h-8 min-w-8 items-center justify-center rounded-lg text-slate-400 transition hover:bg-slate-100 hover:text-slate-700 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-brand-500 disabled:cursor-not-allowed disabled:opacity-40 dark:hover:bg-slate-800 dark:hover:text-white" :disabled="busy || table.loading || table.page >= table.pages" aria-label="Last page" @click="emit('paginate', table.pages - table.page)"><ChevronsRight :size="14" /></button></nav><span>Page {{ table.page }} of {{ Math.max(1, table.pages) }} · {{ table.total }} records</span></footer>
  </section>
</template>
